  lights.add(rim);
  lights.userData.reviewMode = mode;
  lights.userData.lightingFromPhoto = [{"id": "key", "type": "directional", "directionHint": [-0.45, 0.85, 0.3], "colorHint": "#dfe9f2", "intensityHint": 1.8, "evidence": "Mound's upper-left lobes carry the brightest lit faces (rgb 52-103, 68-118, 97-156) while right-side crevices fall to the darkest cluster."}, {"id": "fill", "type": "hemisphere", "directionHint": [0, 1, 0], "colorHint": "#8fb4d4", "intensityHint": 0.9, "evidence": "Shadowed faces stay legible mid-dark rather than going black: a sky fill is present."}, {"id": "crystal-spill", "type": "point", "directionHint": [-0.12, 1.0, 0.05], "colorHint": "#3f9df5", "intensityHint": 1.4, "evidence": "Rock faces near the spire read bluer than the key light alone would leave them."}, {"id": "exposure", "type": "environment", "directionHint": [0, 1, 0], "colorHint": "#ffffff", "intensityHint": 1.0, "evidence": "ACES filmic tone mapping intent; the glow should bloom-clamp, not clip to white."}, {"id": "ground-contact", "type": "contact-shadow", "directionHint": [0, 1, 0], "colorHint": "#000000", "intensityHint": 0.6, "evidence": "The mound sits on the ground plane; a soft ambient-occlusion contact shadow under the skirt keeps it planted. AO term also darkens crevices."}];
  lights.userData.lookDevTargets = {"qualityPriority": "reference-fidelity", "materialPass": {"albedoPaletteRequired": true, "roughnessVariationRequired": true, "normalOrBumpRequired": true, "localOverridesRequired": true, "minimumTextureResolution": 1024, "preferredTextureResolution": 2048, "independentMapChannels": ["albedo", "roughness", "height", "normal", "ambient-occlusion"], "requiredSurfaceFrequencyBands": ["macro", "meso", "micro"], "geometryReliefRequiredWhenSilhouetteAffected": true, "referencePbrExtraction": {"requiredWhenSourceImagePresent": true, "targetThreshold": 0.7, "stopOnLowConfidence": true, "script": "forge/stage1_intake/extract_pbr_evidence.py", "acceptedLimitation": "single-image extraction is reference-derived inference, not exact photogrammetry"}, "mustAvoid": ["single flat albedo per material", "uniform roughness", "albedo texture reused as roughness/height/normal/AO", "single-frequency random noise", "plastic-looking smooth bark, stone, cloth, foliage, or aged material", "local color/detail described only in prose without material masks", "claiming exact PBR recovery when confidence is below the target threshold"]}, "lightingPass": {"requiredTerms": ["key light", "fill light", "rim or environment light", "exposure", "tone mapping", "background", "contact shadow"], "mustAvoid": ["ambient-only lighting", "flat value range", "missing contact shadow", "reference lighting copied without separating material readability"]}, "screenshotReview": ["Compare albedo palette and local color zones.", "Compare roughness/normal/bump response under light.", "Compare cavity dirt, edge wear, stains, moss, scratches, or other local masks.", "Compare key/fill/rim structure, exposure, tone mapping, background, and contact shadows.", "Capture a neutral-light render to verify material readability without reference lighting.", "Capture a grazing-light close-up to expose flat normals, uniform roughness, tiling, and plastic highlights.", "Capture a reference-matched render from the same camera framing as the source."]};
